const buffer = new ArrayBuffer(8);
const bytes = new Uint8Array(buffer);
const words = new Uint16Array(buffer, 2, 2);

bytes[2] = 0x34;
bytes[3] = 0x12;
console.log(words[0].toString(16)); // platform byte order: often 1234
console.log(bytes.byteLength);      // 8
console.log(words.byteOffset);      // 2
console.log(words.length);         // 2 elements

// Main thread: worker is an existing Worker instance.
const buffer = new ArrayBuffer(1_000_000);
const pixels = new Uint8Array(buffer);
pixels[0] = 255;

worker.postMessage({ buffer }, [buffer]);
console.log(buffer.byteLength); // 0: ownership moved away

// In worker.js, the receiver creates its own view:
self.onmessage = ({ data }) => {
  const receivedPixels = new Uint8Array(data.buffer);
  self.postMessage({ firstPixel: receivedPixels[0] });
};

